<?php get_header();?><main id="main" class="lmh-section"><div class="lmh-shell lmh-reading"><?php while(have_posts()):the_post();$type=get_post_type();$id=get_the_ID();?><article><div class="lmh-kicker"><?php echo esc_html(get_post_type_object($type)->labels->singular_name);?></div><h1 class="lmh-title"><?php the_title();?></h1><?php if(has_post_thumbnail())the_post_thumbnail('large');the_content();?><dl class="lmh-details"><?php
foreach(get_registered_meta_keys('post',$type) as $key=>$schema){$value=get_post_meta($id,$key,true);if(!$value || strpos($key,'_lmh_')!==0 || in_array($key,['_lmh_video_url','_lmh_audio_url','_lmh_stream_url'],true))continue;$label=ucwords(str_replace('_',' ',substr($key,5)));echo '<dt>'.esc_html($label).'</dt><dd>';if(preg_match('#^https?://#i',$value))echo '<a href="'.esc_url($value).'" rel="noopener">'.esc_html($label).' →</a>';else echo esc_html($value);echo '</dd>';}
foreach(get_object_taxonomies($type,'objects') as $tax){echo get_the_term_list($id,$tax->name,'<dt>'.esc_html($tax->label).'</dt><dd>',', ','</dd>')?:'';}?></dl>
<?php foreach(['_lmh_video_url'=>'video','_lmh_audio_url'=>'audio','_lmh_stream_url'=>'audio'] as $key=>$format){$url=get_post_meta($id,$key,true);if(!$url)continue;$url=esc_url($url);if(!$url)continue;if($format==='video' && preg_match('/\.(mp4|webm)(\?.*)?$/i',$url))echo wp_video_shortcode(['src'=>$url]);elseif($format==='audio')echo wp_audio_shortcode(['src'=>$url]);else {$embed=wp_oembed_get($url);echo $embed?:'<p><a class="lmh-btn" href="'.$url.'" rel="noopener">WATCH PROGRAM →</a></p>';}}
if($type==='lmh_artist'): $following=array_map('intval',(array)get_user_meta(get_current_user_id(),'lmh_following',true));?><button class="lmh-btn" data-follow="<?php echo esc_attr($id);?>" aria-pressed="<?php echo in_array($id,$following,true)?'true':'false';?>"><?php echo in_array($id,$following,true)?'UNFOLLOW ARTIST':'FOLLOW ARTIST';?></button><p id="follow-status" role="status"></p><?php endif;?>
<?php if(in_array($type,['lmh_artist','lmh_professional','lmh_company'],true)):?><section class="lmh-squad"><h2>Request a booking</h2><?php if(!is_user_logged_in()):?><a class="lmh-btn" href="<?php echo esc_url(wp_login_url(get_permalink()));?>">SIGN IN TO REQUEST A BOOKING</a><?php else:?><form class="lmh-form" data-api="bookings"><input type="hidden" name="talent_id" value="<?php echo esc_attr($id);?>"><label>Event date<input type="date" name="event_date" required min="<?php echo esc_attr(current_time('Y-m-d'));?>"></label><label>Budget & currency<input name="budget" required maxlength="100" placeholder="e.g. USD 2,000"></label><label>Tell us about your event<textarea name="message" required maxlength="5000" rows="5"></textarea></label><button class="lmh-btn">SEND BOOKING REQUEST</button><p role="status" aria-live="polite"></p></form><?php endif;?></section><?php endif;?></article><?php endwhile;?></div></main><?php get_footer();?>
